-- Rollback of migration 009 (evaluation), generated by focus.migrations.rollback_script from the forward
-- script's declared objects. Recovery is forward by default; this exists for an install that has just failed review.
-- The runner executes it in one transaction under sp_getapplock('FOCUS_FN_MIGRATIONS'); any guard stops it whole.
-- Nothing here deletes a row.
SET XACT_ABORT ON;
DROP VIEW IF EXISTS WEB_APP.FOCUS_FN_TeamXp;
DROP VIEW IF EXISTS WEB_APP.FOCUS_FN_CurrentEvaluation;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_AppendEvaluation;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_BadgeAward_Immutable;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_RecognitionEvent_Immutable;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_EvaluationEvidence_Immutable;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_Evaluation_Immutable;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_BadgeAward) THROW 51951, 'WEB_APP.FOCUS_FN_BadgeAward holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_BadgeAward;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_RecognitionEvent) THROW 51952, 'WEB_APP.FOCUS_FN_RecognitionEvent holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_RecognitionEvent;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_EvaluationHead) THROW 51953, 'WEB_APP.FOCUS_FN_EvaluationHead holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_EvaluationHead;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_EvaluationEvidence) THROW 51954, 'WEB_APP.FOCUS_FN_EvaluationEvidence holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_EvaluationEvidence;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP CONSTRAINT IF EXISTS CK_FN_Evaluation_NullScore;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP CONSTRAINT IF EXISTS CK_FN_Evaluation_Status;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_Evaluation WHERE Label IS NOT NULL) THROW 51955, 'WEB_APP.FOCUS_FN_Evaluation.Label holds values; recover forward with a new migration', 1;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP COLUMN IF EXISTS Label;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP CONSTRAINT IF EXISTS CK_FN_Evaluation_PolicyStatus;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_Evaluation WHERE PolicyStatus IS NOT NULL) THROW 51956, 'WEB_APP.FOCUS_FN_Evaluation.PolicyStatus holds values; recover forward with a new migration', 1;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP COLUMN IF EXISTS PolicyStatus;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP CONSTRAINT IF EXISTS CK_FN_Evaluation_Revision;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_Evaluation WHERE Revision IS NOT NULL) THROW 51957, 'WEB_APP.FOCUS_FN_Evaluation.Revision holds values; recover forward with a new migration', 1;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP COLUMN IF EXISTS Revision;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP CONSTRAINT IF EXISTS CK_FN_Evaluation_Kind;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_Evaluation WHERE Kind IS NOT NULL) THROW 51958, 'WEB_APP.FOCUS_FN_Evaluation.Kind holds values; recover forward with a new migration', 1;
ALTER TABLE WEB_APP.FOCUS_FN_Evaluation DROP COLUMN IF EXISTS Kind;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_Evaluation WHERE SeriesKey IS NOT NULL) THROW 51959, 'WEB_APP.FOCUS_FN_Evaluation.SeriesKey holds values; recover forward with a new migration', 1;
